/// The keywords `name`'s value must be one of, when Blink parses it as a single keyword.
pub fn single_keyword(name: &str) -> Option<&'static [&'static str]> {
    let i = BLINK_KEYWORD_PROPERTIES.binary_search_by(|(n, _)| (*n).cmp(name)).ok()?;
    Some(BLINK_KEYWORD_PROPERTIES[i].1)
}

/// Whether a transition runs on property `name` without `allow-discrete`: Blink can interpolate its values.
pub fn transitionable(name: &str) -> bool {
    BLINK_TRANSITIONABLE.binary_search(&name).is_ok()
}

/// The property `name` stands for when Blink exposes it: itself, or an alias's target.
pub fn exposed(name: &str) -> Option<&'static str> {
    let i = BLINK_CSS_NAMES.binary_search_by(|(n, _)| (*n).cmp(name)).ok()?;
    let (n, alias) = BLINK_CSS_NAMES[i];
    Some(alias.unwrap_or(n))
}
